mapper.select:
select

from
case_center_info_follow
where 1=1

    and case_name like CONCAT('%',#{caseName,jdbcType=VARCHAR},'%')


    and case_no like CONCAT('%',#{caseNo,jdbcType=VARCHAR},'%')


    and gradation_state = #{gradationState,jdbcType=INTEGER}


    and case_state = #{caseState,jdbcType=INTEGER}


    and follow_type = #{followType,jdbcType=INTEGER}


order by follow_time desc limit #{pageIndex} , #{pageSize}
